code='''from collections import deque

def transform(grid):
    h, w = len(grid), len(grid[0])
    seen = set()
    objects = []
    for r in range(h):
        for c in range(w):
            if grid[r][c] == 0 or (r, c) in seen:
                continue
            color = grid[r][c]
            q = [(r, c)]
            seen.add((r, c))
            cells = []
            while q:
                y, x = q.pop()
                cells.append((y, x))
                for ny, nx in ((y-1,x),(y+1,x),(y,x-1),(y,x+1)):
                    if 0 <= ny < h and 0 <= nx < w and (ny,nx) not in seen and grid[ny][nx] == color:
                        seen.add((ny,nx))
                        q.append((ny,nx))
            minr = min(r for r, c in cells)
            maxr = max(r for r, c in cells)
            minc = min(c for r, c in cells)
            maxc = max(c for r, c in cells)
            exterior = set()
            q = deque()
            for r in range(minr, maxr + 1):
                for c in range(minc, maxc + 1):
                    if (r in (minr, maxr) or c in (minc, maxc)) and grid[r][c] == 0 and (r,c) not in exterior:
                        exterior.add((r,c)); q.append((r,c))
            while q:
                r, c = q.popleft()
                for nr, nc in ((r-1,c),(r+1,c),(r,c-1),(r,c+1)):
                    if minr <= nr <= maxr and minc <= nc <= maxc and grid[nr][nc] == 0 and (nr,nc) not in exterior:
                        exterior.add((nr,nc)); q.append((nr,nc))
            has_hole = any(grid[r][c] == 0 and (r,c) not in exterior
                           for r in range(minr, maxr + 1) for c in range(minc, maxc + 1))
            objects.append({'color': color, 'cells': cells, 'top': has_hole,
                            'minr': minr, 'maxr': maxr})

    out = [[0] * w for _ in range(h)]
    occupied = set()
    # Hollow objects pack against the top; solid objects pack against the bottom.
    for obj in sorted((o for o in objects if o['top']), key=lambda o: o['minr']):
        cells = obj['cells']
        shift = -obj['minr']
        while shift < 0 and all((r + shift - 1, c) not in occupied for r, c in cells):
            shift -= 1
        for r, c in cells:
            nr = r + shift
